package com.tothetop;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ToTheTopPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ToTheTopPlugin.class);
		RuneLite.main(args);
	}
}

package com.tothetop;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ToTheTopConfig.GROUP)
public interface ToTheTopConfig extends Config
{
	String GROUP = "tothetop";
	String KEY_ITEMS = "items";

	@ConfigItem(
		keyName = KEY_ITEMS,
		name = "Items",
		description = "Newline-separated list of items to track. Edited from the side panel.",
		hidden = true
	)
	default String items()
	{
		return "";
	}
}

package com.tothetop;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.function.Consumer;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

class ToTheTopPanel extends PluginPanel
{
	private final JTextArea textArea;
	private final Consumer<String> onSave;

	ToTheTopPanel(String initialText, Consumer<String> onSave)
	{
		super(false);
		this.onSave = onSave;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout(0, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel header = new JLabel("Items (one per line)");
		header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		add(header, BorderLayout.NORTH);

		textArea = new JTextArea(initialText == null ? "" : initialText);
		textArea.setLineWrap(false);
		textArea.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 12));
		textArea.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		textArea.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		textArea.setCaretColor(ColorScheme.LIGHT_GRAY_COLOR);
		textArea.setBorder(new EmptyBorder(4, 6, 4, 6));

		textArea.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				ToTheTopPanel.this.onSave.accept(textArea.getText());
			}
		});

		JScrollPane scroll = new JScrollPane(
			textArea,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_AS_NEEDED);
		scroll.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 400));
		scroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);

		JPanel footer = new JPanel(new BorderLayout());
		footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel hint = new JLabel("<html><body style='color:#888'>Changes save automatically when the textbox loses focus.</body></html>");
		footer.add(hint, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	void setText(String text)
	{
		if (text == null)
		{
			text = "";
		}
		if (!text.equals(textArea.getText()))
		{
			textArea.setText(text);
		}
	}
}

package com.tothetop;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "To The Top",
	description = "Hides non-verified ground items on tiles where a verified item is also present, so left-click picks up the verified item first.",
	tags = {"items", "drops", "loot", "ground", "pickup"}
)
public class ToTheTopPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ToTheTopConfig config;

	private ToTheTopPanel panel;
	private NavigationButton navButton;

	private volatile Set<String> verifiedNames = Collections.emptySet();

	@Provides
	ToTheTopConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ToTheTopConfig.class);
	}

	@Override
	protected void startUp()
	{
		rebuildVerifiedSet();

		panel = new ToTheTopPanel(config.items(), this::saveItems);

		navButton = NavigationButton.builder()
			.tooltip("To The Top")
			.icon(loadIcon())
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		verifiedNames = Collections.emptySet();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ToTheTopConfig.GROUP.equals(event.getGroup()) || !ToTheTopConfig.KEY_ITEMS.equals(event.getKey()))
		{
			return;
		}

		rebuildVerifiedSet();

		if (panel != null)
		{
			final String latest = config.items();
			SwingUtilities.invokeLater(() -> panel.setText(latest));
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (verifiedNames.isEmpty())
		{
			return;
		}

		final MenuEntry entry = event.getMenuEntry();
		if (!isGroundItemTake(entry.getType()))
		{
			return;
		}

		final Tile tile = sceneTile(entry.getParam0(), entry.getParam1());
		if (tile == null)
		{
			return;
		}

		final List<TileItem> tileItems = tile.getGroundItems();
		if (tileItems == null || tileItems.isEmpty())
		{
			return;
		}

		if (!tileHasVerifiedItem(tileItems))
		{
			return;
		}

		final String entryName = itemName(entry.getIdentifier());
		if (entryName == null || isVerified(entryName))
		{
			return;
		}

		// This entry is for a non-verified item on a tile that also has a
		// verified item — strip it from the menu. When the verified items
		// are picked up, this branch stops firing and entries reappear.
		final Menu menu = client.getMenu();
		final MenuEntry[] filtered = Arrays.stream(menu.getMenuEntries())
			.filter(e -> e != entry)
			.toArray(MenuEntry[]::new);
		menu.setMenuEntries(filtered);
	}

	private boolean tileHasVerifiedItem(List<TileItem> items)
	{
		for (TileItem ti : items)
		{
			final String name = itemName(ti.getId());
			if (name != null && isVerified(name))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isVerified(String itemName)
	{
		return verifiedNames.contains(itemName.toLowerCase(Locale.ROOT));
	}

	private String itemName(int itemId)
	{
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		final String name = comp == null ? null : comp.getName();
		return (name == null || name.isEmpty() || "null".equals(name)) ? null : name;
	}

	private Tile sceneTile(int sceneX, int sceneY)
	{
		if (sceneX < 0 || sceneY < 0)
		{
			return null;
		}
		final WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			return null;
		}
		final Scene scene = view.getScene();
		if (scene == null)
		{
			return null;
		}
		final Tile[][][] tiles = scene.getTiles();
		final int plane = view.getPlane();
		if (plane < 0 || plane >= tiles.length
			|| sceneX >= tiles[plane].length
			|| sceneY >= tiles[plane][sceneX].length)
		{
			return null;
		}
		return tiles[plane][sceneX][sceneY];
	}

	private static boolean isGroundItemTake(MenuAction type)
	{
		switch (type)
		{
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	private void rebuildVerifiedSet()
	{
		final String raw = config.items();
		if (raw == null || raw.isEmpty())
		{
			verifiedNames = Collections.emptySet();
			return;
		}

		final Set<String> built = new HashSet<>();
		for (String line : raw.split("\\R"))
		{
			final String trimmed = line.trim();
			if (!trimmed.isEmpty())
			{
				built.add(trimmed.toLowerCase(Locale.ROOT));
			}
		}
		verifiedNames = built;
	}

	private void saveItems(String text)
	{
		configManager.setConfiguration(ToTheTopConfig.GROUP, ToTheTopConfig.KEY_ITEMS, text == null ? "" : text);
	}

	private static BufferedImage loadIcon()
	{
		final BufferedImage img = ImageUtil.loadImageResource(ToTheTopPlugin.class, "icon.png");
		return img != null ? img : buildPlaceholderIcon();
	}

	private static BufferedImage buildPlaceholderIcon()
	{
		final BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setColor(new Color(200, 160, 60));
			g.fillRoundRect(2, 2, 12, 12, 4, 4);
			g.setColor(new Color(60, 40, 10));
			g.drawRoundRect(2, 2, 12, 12, 4, 4);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}
}
